<template><div class="not-found"><div class="orbit" aria-hidden="true"><span></span><b>404</b></div><h2>页面走丢了</h2><p>你访问的页面不存在，可能已被移动或删除。</p><el-button type="primary" @click="$router.push('/dashboard')"><el-icon><Back /></el-icon>返回首页</el-button></div></template>
<style scoped>.not-found{min-height:calc(100vh - 190px);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.not-found h2{margin:22px 0 8px}.not-found p{margin:0 0 22px;color:#8995a8}.orbit{position:relative;width:150px;height:150px;display:grid;place-items:center;border-radius:50%;border:1px solid rgba(var(--accent-rgb),.15);background:radial-gradient(circle,rgba(var(--accent-rgb),.09),transparent 65%)}.orbit b{font-size:38px;color:var(--accent)}.orbit span{position:absolute;inset:10px;border:1px dashed rgba(var(--accent-rgb),.3);border-radius:50%;animation:orbit-spin 12s linear infinite}.orbit span::after{content:"";position:absolute;top:-5px;left:50%;width:10px;height:10px;border-radius:50%;background:var(--accent);box-shadow:0 0 14px rgba(var(--accent-rgb),.55)}@keyframes orbit-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.orbit span{animation:none}}</style>
